package org.millenaire.common.utilities;import net.minecraft.core.BlockPos;import net.minecraft.world.level.Level;import net.minecraft.world.level.block.*;import net.minecraft.world.level.block.state.BlockState;import java.util.*;public class Point {public static Map<BlockPos,BlockState> world=new HashMap<>();public BlockPos pos;public Point(int x,int y,int z){pos=new BlockPos(x,y,z);}public Point getRelative(int x,int y,int z){return new Point(pos.getX()+x,pos.getY()+y,pos.getZ()+z);}public BlockState getBlockActualState(Level w){return world.getOrDefault(pos,Blocks.AIR.defaultBlockState());}public Block getBlock(Level w){return getBlockActualState(w).getBlock();}public double horizontalDistanceToSquared(net.minecraft.world.entity.Entity v){return 0;}}